public class Never {
    static class F { @Override protected void finalize() {
        System.out.println("    [finalize] " + hashCode()); } }
    public static void main(String[] a) {
        for (int i = 0; i < 5; i++) new F();
        System.out.println("  5개를 버리고 그냥 끝낸다 (System.gc() 안 부름)");
    }
}

